@RunWith(SpringRunner.class)
@WebMvcTest(CrashController.class)
public class CrashControllerTest {}
/**************TEST METHOD BEGIN*************/
@Test
public void triggerException_resolvedException_isRuntimeException(){
        try {
            MvcResult result = mockMvc.perform(get("/oups")).andReturn();
            // If no exception was rethrown, check resolvedException or status
            if (result.getResolvedException() != null) {
                assertThat(result.getResolvedException()).isInstanceOf(RuntimeException.class);
            } else {
                assertThat(result.getResponse().getStatus()).isGreaterThanOrEqualTo(500);
            }
        } catch (NestedServletException e) {
            assertThat(e.getCause()).isInstanceOf(RuntimeException.class);
        } catch (Exception e) {
            // Any other exception wrapping the RuntimeException is acceptable
            Throwable root = e;
            while (root.getCause() != null) root = root.getCause();
            assertThat(root).isInstanceOf(RuntimeException.class);
        }
    }
/**************TEST METHOD END*************/


